.ac-menu-movil-barra{margin:0.6rem 0.6rem 0;display:flex;align-items:center;padding:0.6rem 0.6rem 0.6rem 1rem;border-radius:20px;border:1px solid rgba(255, 255, 255, 0.12);background:rgba(38, 39, 47,0.72);backdrop-filter:blur(16px)}
.ac-menu-movil-logo{font-family:'Anton',sans-serif;font-size:1.2rem;letter-spacing:0.04em}
.ac-menu-movil-hamb{margin-left:auto;display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:9px;border:1px solid rgba(255, 255, 255, 0.16);background:transparent;color:rgba(255, 255, 255, 0.62);cursor:pointer;touch-action:manipulation;transition:transform 0.1s ease-out}
