.ac-menu-movil-pagina{padding:1rem 1.25rem}
.ac-menu-movil-miga{margin:0 0 0.25rem;font-size:0.72rem;font-weight:600;text-transform:uppercase;letter-spacing:0.15em;color:rgba(255, 255, 255, 0.5)}
.ac-menu-movil-h1{margin:0;font-size:1.6rem}
.ac-menu-movil-fondo{position:absolute;inset:0;background:rgba(0,0,0,0.5);opacity:0;pointer-events:none;transition:opacity 0.2s cubic-bezier(0.25, 0.1, 0.25, 1)}
.ac-menu-movil.ac-menu-movil-abierto .ac-menu-movil-fondo{opacity:1;pointer-events:auto}
.ac-menu-movil-panel{position:absolute;top:0.6rem;right:0.6rem;bottom:0.6rem;width:min(82%,300px);border-radius:22px;border:1px solid rgba(255, 255, 255, 0.12);background:rgba(38, 39, 47,0.92);backdrop-filter:blur(18px) saturate(140%);box-shadow:0 24px 60px -20px rgba(0,0,0,0.6);padding:1rem 0.8rem;display:flex;flex-direction:column;gap:2px;overflow-y:auto;transform:translateX(calc(100% + 1rem));transition:transform 0.2s cubic-bezier(0.25, 0.1, 0.25, 1)}
.ac-menu-movil.ac-menu-movil-abierto .ac-menu-movil-panel{transform:translateX(0)}
.ac-menu-movil-cerrar{align-self:flex-end;display:grid;place-items:center;width:36px;height:36px;margin-bottom:0.4rem;border-radius:999px;border:1px solid rgba(255, 255, 255, 0.16);background:transparent;color:rgba(255, 255, 255, 0.62);cursor:pointer}
.ac-menu-movil-cerrar svg{width:18px;height:18px}
.ac-menu-movil-sec{margin:0 0 0.6rem;padding:0 1rem;font-size:0.72rem;font-weight:600;text-transform:uppercase;letter-spacing:0.15em;color:rgba(255, 255, 255, 0.5)}
.ac-menu-movil-enl{display:flex;align-items:center;gap:0.6rem;padding:0.6rem 0.8rem;border-radius:999px;color:rgba(255, 255, 255, 0.62);text-decoration:none;font-weight:500;font-size:0.8rem}
.ac-menu-movil-enl svg{width:18px;height:18px;flex-shrink:0;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.ac-menu-movil-enl:hover{background:rgba(255, 255, 255, 0.08);color:#ffffff}
.ac-menu-movil-enl:hover svg,.ac-menu-movil-enl.ac-menu-movil-activo svg{color:#ff3b30}
.ac-menu-movil-enl.ac-menu-movil-activo{background:rgba(224, 43, 32, 0.12);box-shadow:inset 0 0 0 1px rgba(224,43,32,0.25);color:#ffffff}
.ac-menu-movil-sep{height:1px;background:rgba(255, 255, 255, 0.12);margin:0.8rem 0}
.ac-menu-movil-salir{text-align:center;font-size:0.8rem;color:rgba(255, 255, 255, 0.62);text-decoration:none;padding:0.6rem 0.8rem;border:1px solid rgba(255, 255, 255, 0.16);border-radius:9px}

piezas.js:
(function(){document.querySelectorAll('.ac-menu-movil').forEach(function(r){
  var b=r.querySelector('.ac-menu-movil-hamb');
  function f(abrir){r.classList.toggle('ac-menu-movil-abierto',abrir);b.setAttribute('aria-expanded',abrir?'true':'false');}
  b.addEventListener('click',function(){f(true);});
  r.querySelector('.ac-menu-movil-cerrar').addEventListener('click',function(){f(false);});
  r.querySelector('.ac-menu-movil-fondo').addEventListener('click',function(){f(false);});
});})();

