piezas.js:
(function(){document.querySelectorAll('.ac-barra-filtros').forEach(function(r){
  var q=r.querySelector('.ac-barra-filtros-q'),t;var norm=function(s){return s.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();};
  function filtrar(){var v=norm(q.value.trim()),n=0;r.querySelectorAll('.ac-barra-filtros-lista li').forEach(function(li){var ok=norm(li.textContent).indexOf(v)>-1;li.hidden=!ok;if(ok)n++;});r.querySelector('.ac-barra-filtros-vacio').hidden=n>0;}
  q.addEventListener('input',function(){clearTimeout(t);t=setTimeout(filtrar,350);});
  r.querySelector('.ac-barra-filtros-limpiar').addEventListener('click',function(e){e.preventDefault();q.value='';r.querySelectorAll('select').forEach(function(s){s.selectedIndex=0;});filtrar();});
});})();

