piezas.js:
(function(){document.querySelectorAll('.ac-modal-confirmacion').forEach(function(r){
  var f=r.querySelector('.ac-modal-confirmacion-fondo'),res=r.querySelector('.ac-modal-confirmacion-res');
  function cerrar(ok){f.classList.remove('ac-modal-confirmacion-visible');setTimeout(function(){f.hidden=true;},200);res.textContent=ok?'Confirmado: se archivaría.':'Cancelado.';}
  r.querySelector('.ac-modal-confirmacion-abrir').addEventListener('click',function(){f.hidden=false;requestAnimationFrame(function(){f.classList.add('ac-modal-confirmacion-visible');});f.querySelector('[data-cancelar]').focus();});
  f.querySelector('[data-cancelar]').addEventListener('click',function(){cerrar(false);});
  f.querySelector('[data-confirmar]').addEventListener('click',function(){cerrar(true);});
  f.addEventListener('click',function(e){if(e.target===f)cerrar(false);});
  r.addEventListener('keydown',function(e){if(e.key==='Escape'&&!f.hidden)cerrar(false);});
});})();

