(function(){document.querySelectorAll('.ac-accion-en-bloque-flotante').forEach(function(r){
  var f=r.querySelector('.ac-accion-en-bloque-flotante-flot');
  function act(){var t=r.querySelectorAll('[data-lado=t]:checked').length,a=r.querySelectorAll('[data-lado=a]:checked').length;
    r.querySelector('[data-n=t]').textContent=t;r.querySelector('[data-n=a]').textContent=a;f.hidden=!(t>0&&a>0);}
  r.querySelectorAll('input[data-lado]').forEach(function(i){i.addEventListener('change',act);});
});})();

