(function(){

document.querySelectorAll('.ac-campos-formulario-ojo').forEach(function(b){b.addEventListener('click',function(){var i=b.parentNode.querySelector('input');var v=i.type==='password';i.type=v?'text':'password';b.classList.toggle('ac-campos-formulario-mostrando',v);b.setAttribute('aria-label',v?'Ocultar contraseña':'Mostrar contraseña');});});

document.querySelectorAll('.ac-campos-formulario-form').forEach(function(f){
  function limpiar(el){el.classList.remove('ac-campos-formulario-invalido');var a=el.closest('.ac-campos-formulario-pass')||el;var s=a.nextElementSibling;if(s&&s.classList.contains('ac-campos-formulario-error'))s.remove();}
  function msg(el){var v=el.validity;if(v.valueMissing)return el.tagName==='SELECT'?'Selecciona una opción.':'Completa todos los campos.';if(v.typeMismatch&&el.type==='email')return 'El correo no tiene un formato válido.';if(v.tooShort)return 'Debe tener al menos '+el.minLength+' caracteres.';return 'Revisa el formulario.';}
  f.addEventListener('submit',function(e){e.preventDefault();var els=[].slice.call(f.elements);els.forEach(limpiar);
    for(var i=0;i<els.length;i++){var el=els[i];if(!el.willValidate||el.checkValidity())continue;el.classList.add('ac-campos-formulario-invalido');
      var p=document.createElement('p');p.className='ac-campos-formulario-error';p.innerHTML='<span class="ac-campos-formulario-error-i" aria-hidden="true">✕</span><span></span>';p.lastChild.textContent=msg(el);
      (el.closest('.ac-campos-formulario-pass')||el).insertAdjacentElement('afterend',p);el.focus();return;}});
  f.addEventListener('input',function(e){if(e.target.classList.contains('ac-campos-formulario-invalido'))limpiar(e.target);});
});})();

