(function(){var IC={error:'✕',exito:'✓',aviso:'!',info:'i'},DUR={error:7000,exito:4000,aviso:4000,info:4000};
document.querySelectorAll('.ac-toast').forEach(function(r){var c=r.querySelector('.ac-toast-notis');
  function notificar(txt,tono){c.querySelectorAll('.ac-toast-noti').forEach(function(n){n.remove();});
    var n=document.createElement('div');n.className='ac-toast-noti ac-toast-'+tono;n.setAttribute('role','status');
    n.innerHTML='<span class="ac-toast-ni" aria-hidden="true">'+IC[tono]+'</span><span class="ac-toast-nt"></span>';n.lastChild.textContent=txt;c.appendChild(n);
    requestAnimationFrame(function(){n.classList.add('ac-toast-visible');});
    function cerrar(){n.classList.remove('ac-toast-visible');setTimeout(function(){n.remove();},400);}
    n.addEventListener('click',cerrar);setTimeout(cerrar,Math.max(DUR[tono],1500+txt.length*50));}
  r.querySelectorAll('[data-tono]').forEach(function(b){b.addEventListener('click',function(){notificar(b.dataset.txt,b.dataset.tono);});});
});})();

