(function(){document.querySelectorAll('.ac-fila-accion-caja .ac-fila-accion-lista').forEach(function(ul){var arr=null;
  ul.querySelectorAll('.ac-fila-accion-fila').forEach(function(li){var h=li.querySelector('.ac-fila-accion-agarre');if(!h)return;
    h.addEventListener('mousedown',function(){li.draggable=true;});
    li.addEventListener('dragstart',function(){arr=li;li.classList.add('ac-fila-accion-arrastrando');});
    li.addEventListener('dragend',function(){li.classList.remove('ac-fila-accion-arrastrando');li.draggable=false;arr=null;});
    li.addEventListener('dragover',function(e){e.preventDefault();if(!arr||arr===li)return;var r=li.getBoundingClientRect();ul.insertBefore(arr,e.clientY<r.top+r.height/2?li:li.nextSibling);});
  });
});})();

