.ac-arbol-casillas{font-family:'Inter',sans-serif;font-size:0.9rem;color:#ffffff;background:#15161b;padding:1.5rem;border-radius:12px;-webkit-font-smoothing:antialiased;color-scheme:dark;line-height:1.4}
.ac-arbol-casillas *{box-sizing:border-box}
.ac-arbol-casillas h1,.ac-arbol-casillas h2,.ac-arbol-casillas h3,.ac-arbol-casillas h4{font-family:'Anton',sans-serif;font-weight:400;letter-spacing:0.01em}
.ac-arbol-casillas a{color:inherit}
.ac-arbol-casillas label{display:flex;flex-direction:column;gap:0.4rem;font-size:0.8rem;color:rgba(255, 255, 255, 0.62)}
.ac-arbol-casillas input:not([type=checkbox]):not([type=radio]):not([type=file]),.ac-arbol-casillas select,.ac-arbol-casillas textarea{font-family:inherit;font-size:0.9rem;color:#ffffff;padding:0.8rem 1rem;border-radius:14px;border:1px solid rgba(255, 255, 255, 0.18);background:rgba(0, 0, 0, 0.35);transition:border-color 0.2s cubic-bezier(0.25, 0.1, 0.25, 1),box-shadow 0.2s cubic-bezier(0.25, 0.1, 0.25, 1)}
