(function(){document.querySelectorAll('.ac-arbol-casillas-grupo').forEach(function(g){
  var todo=g.querySelector('.ac-arbol-casillas-todo');var hijos=g.querySelectorAll('.ac-arbol-casillas-fila input');
  todo.addEventListener('click',function(e){e.stopPropagation();});
  todo.addEventListener('change',function(){hijos.forEach(function(h){h.checked=todo.checked;});});
  hijos.forEach(function(h){h.addEventListener('change',function(){var n=[].filter.call(hijos,function(x){return x.checked;}).length;todo.checked=n===hijos.length;todo.indeterminate=n>0&&n<hijos.length;});});
});})();

