document.querySelectorAll('.ce-listado__pestanas').forEach(function (nav) {
  nav.addEventListener('click', function (e) {
    var a = e.target.closest('.ce-listado__pestana');
    if (!a) return;
    e.preventDefault();
    nav.querySelectorAll('.ce-listado__pestana').forEach(function (p) { p.removeAttribute('aria-current'); });
    a.setAttribute('aria-current', 'page');
  });
});

