document.querySelectorAll('[data-um-bloque]').forEach(function (r) {
  var barra = r.querySelector('.um-acciones-bloque__barra'), filas = r.querySelectorAll('[data-fila]'), accion = r.querySelector('[data-accion]');
  function pintar() { var n = r.querySelectorAll('[data-fila]:checked').length; barra.hidden = n === 0; r.querySelector('[data-contador]').textContent = n + (n === 1 ? ' seleccionado' : ' seleccionados'); }
  filas.forEach(function (c) { c.addEventListener('change', pintar); });
  r.querySelector('[data-todos]').addEventListener('change', function (e) { filas.forEach(function (c) { c.checked = e.target.checked; }); pintar(); });
  accion.addEventListener('change', function () { r.querySelector('[data-aplicar]').disabled = !accion.value; r.querySelector('.um-acciones-bloque__cursos').hidden = !/asignar|quitar/.test(accion.value); });
  r.querySelector('[data-limpiar]').addEventListener('click', function () { filas.forEach(function (c) { c.checked = false; }); r.querySelector('[data-todos]').checked = false; pintar(); });
});

