.um-skeleton-demo{font-family:'DM Sans', system-ui, sans-serif;color:#000;background:#f4f7f6;padding:1.5rem;box-sizing:border-box}
.um-skeleton{display:block;position:relative;overflow:hidden;background:#def1ec;border-radius:8px}
.um-skeleton::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent 0%,rgba(255,255,255,.55) 50%,transparent 100%);transform:translateX(-100%);animation:um-skeleton-brillo 1.4s ease-in-out infinite}
