.um-interruptor-demo{font-family:'DM Sans', system-ui, sans-serif;color:#000;background:#f4f7f6;padding:1.5rem;box-sizing:border-box;display:flex;gap:1.5rem;flex-wrap:wrap}
.um-interruptor{position:relative;display:inline-flex;align-items:center;gap:.45rem;font-size:.76rem;font-weight:600;color:#555;cursor:pointer;user-select:none;white-space:nowrap}
.um-interruptor input{position:absolute;opacity:0;width:1px;height:1px}
.um-interruptor__pista{position:relative;width:34px;height:20px;flex-shrink:0;border-radius:999px;background:#d5dcd9;transition:background .15s}
.um-interruptor__pista::after{content:'';position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.2);transition:transform .15s}
.um-interruptor input:checked + .um-interruptor__pista{background:#2e7d55}
.um-interruptor input:checked + .um-interruptor__pista::after{transform:translateX(14px)}
.um-interruptor input:focus-visible + .um-interruptor__pista{outline:2px solid #b3e8da;outline-offset:2px}
.um-interruptor input:disabled + .um-interruptor__pista{opacity:.5}
.um-interruptor input:checked ~ .um-interruptor__txt{color:#2e7d55}
.um-interruptor--aviso input:not(:checked) ~ .um-interruptor__txt{color:#b3261e}
.um-interruptor--grande .um-interruptor__pista{width:44px;height:24px}
.um-interruptor--grande .um-interruptor__pista::after{width:20px;height:20px}
.um-interruptor--grande input:checked + .um-interruptor__pista::after{transform:translateX(20px)}
@media (prefers-reduced-motion:reduce){.um-interruptor__pista,.um-interruptor__pista::after{transition:none}}

