.re-proximos-status{display:inline-flex;align-items:center;padding:.15rem .6rem;border-radius:980px;background:var(--st-bg,#ecebe2);color:var(--st-ink,#6b6b60);font:500 .78rem/1.4 'Inter Variable', 'Inter', system-ui, sans-serif;white-space:nowrap}
.re-proximos-status[data-status='solicitud'],.re-proximos-status[data-status='pendiente_pago']{--st-bg:#f6f8ce;--st-ink:#8a5700}
