.re-proximos-status[data-status='cancelada'],.re-proximos-status[data-status='rechazada'],.re-proximos-status[data-status='no_show']{--st-bg:#f6e0dc;--st-ink:#c62f2f}

.re-atencion{font-family:'Inter Variable', 'Inter', system-ui, sans-serif;color:#15161a;background:#f5f4ec;padding:1.5rem;box-sizing:border-box;-webkit-font-smoothing:antialiased;background:#fff;border:1px solid rgba(21,22,26,.09);border-radius:18px;box-shadow:0 1px 2px rgba(21,22,26,.04),0 18px 40px -28px rgba(21,22,26,.35);padding:1.6rem 1.8rem}
.re-atencion__ante{margin:0;font:600 .8rem/1.4 'Inter Variable', 'Inter', system-ui, sans-serif}
.re-atencion__titulo{margin:0 0 1.2rem;padding-bottom:.9rem;border-bottom:1px solid rgba(21,22,26,.09);font:800 1.35rem/1.15 'Inter Variable', 'Inter', system-ui, sans-serif;letter-spacing:-.03em}
.re-atencion__lista{display:flex;flex-direction:column;gap:.5rem;margin:0;padding:0;list-style:none}
.re-atencion__lista li{padding:.75rem 1rem;border-left:3px solid;border-radius:0 14px 14px 0;font-size:.93rem}
.re-atencion__lista a{color:inherit;font-weight:600}
.re-atencion--bad{color:#7a1f1f;background:#fbeceb;border-color:#c62f2f}
.re-atencion--warn{color:#6b4300;background:#f9fbe0;border-color:#d6e022}
