.re-atencion__ok{margin:1.2rem 0 0;padding:.9rem 1.1rem;border-radius:12px;background:#eaf5ee;color:#1b4d33;font-size:.93rem}

.re-pestanas-demo{font-family:'Inter Variable', 'Inter', system-ui, sans-serif;color:#15161a;background:#f5f4ec;padding:1.5rem;box-sizing:border-box;-webkit-font-smoothing:antialiased}
.re-pestanas{display:inline-flex;flex-wrap:wrap;gap:4px;padding:4px;border-radius:12px;background:#e9e8de}
.re-pestanas a{display:inline-flex;align-items:center;gap:.45rem;padding:.5rem 1.1rem;border-radius:9px;color:#15161a;font:500 .88rem/1.3 'Inter Variable', 'Inter', system-ui, sans-serif;text-decoration:none;white-space:nowrap;transition:background .15s}
