.re-ficha__nombre{font-size:1.25rem;font-weight:700}
.re-ficha__meta{display:flex;flex-wrap:wrap;align-items:center;gap:.6rem;margin-top:.25rem!important;font-size:.85rem;color:#6b6b60}
