  t.querySelectorAll("button.pill").forEach(p => p.onclick = e => { e.stopPropagation(); const pag = p.classList.contains("pagada"); p.className = "pill " + (pag ? "pendiente" : "pagada"); p.textContent = pag ? "pendiente" : "pagada"; });
