function mjDialogo({ titulo, texto, ok = "Aceptar", cancelar, peligro }) {
  return new Promise(resolve => {
    const d = document.createElement("dialog"), e = s => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;");
    d.className = "mj-dialogo-confirmacion-dlg" + (peligro ? " peligro" : "");
    d.innerHTML = `<div class="mj-dialogo-confirmacion-ic">${peligro ? "!" : "i"}</div><div class="mj-dialogo-confirmacion-txt">${titulo ? `<b>${e(titulo)}</b>` : ""}<p>${e(texto)}</p></div>
      <div class="mj-dialogo-confirmacion-acts">${cancelar ? `<button type="button" class="mj-dialogo-confirmacion-b" data-r="0">${e(cancelar)}</button>` : ""}<button type="button" class="mj-dialogo-confirmacion-b ok" data-r="1">${e(ok)}</button></div>`;
    let hecho = false;
    const fin = r => { if (hecho) return; hecho = true; d.classList.add("cerrando"); setTimeout(() => { d.close(); d.remove(); }, 140); resolve(r); };
    d.addEventListener("click", ev => { const b = ev.target.closest("[data-r]"); if (b) fin(b.dataset.r === "1"); else if (ev.target === d) fin(false); });
    d.addEventListener("cancel", ev => { ev.preventDefault(); fin(false); });
    document.body.appendChild(d); d.showModal(); d.querySelector(peligro ? "[data-r='0']" : "[data-r='1']")?.focus();
  });
}
const PELIGRO = /eliminar|borrar|desconectar|se perderán|sobrescrib/i;
const confirmar = (texto, o = {}) => mjDialogo({ texto, cancelar: "Cancelar", peligro: o.peligro ?? PELIGRO.test(texto), ok: o.ok ?? (/^¿?\s*eliminar/i.test(texto) ? "Eliminar" : "Continuar"), titulo: o.titulo });
const aviso = (texto, o = {}) => mjDialogo({ texto, ok: o.ok || "Entendido", titulo: o.titulo });
document.getElementById("mjDcA").onclick = () => aviso("El enlace se ha copiado al portapapeles.", { titulo: "Listo" });
document.getElementById("mjDcC").onclick = async () => { const r = await confirmar("¿Eliminar esta renovación?"); console.log("confirmado:", r); };

