(() => {
  const el = document.getElementById("mjAtgToast"); let t;
  const toast = (msg, err = false) => { el.textContent = msg; el.className = "toast on" + (err ? " err" : ""); clearTimeout(t); t = setTimeout(() => el.className = "toast", 2600); };
  function autosaver(fn, delay = 700) { let tm; const st = document.getElementById("mjAtgEstado");
    return () => { st.textContent = "Guardando…"; clearTimeout(tm); tm = setTimeout(async () => { try { await fn(); st.textContent = "Guardado ✓"; } catch (e) { st.textContent = "Sin guardar"; toast(e.message, true); } }, delay); }; }
  const save = autosaver(() => new Promise(r => setTimeout(r, 300)));
  document.getElementById("mjAtgInput").oninput = save;
  document.getElementById("mjAtgOk").onclick = () => toast("Enlace copiado");
  document.getElementById("mjAtgErr").onclick = () => toast("No se pudo guardar: sesión caducada", true);
})();

