(() => {
  const todas = ["Clínica Arce", "Panadería Luna", "Taller Sur", "Óptica Ébano", "Academia Norte"];
  const inp = document.getElementById("mjCsInput"), sin = s => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  const pop = Object.assign(document.createElement("div"), { className: "mj-campo-sugerencias-pop", hidden: true }); document.body.appendChild(pop);
  const abrir = filtrar => { const q = filtrar ? sin(inp.value.trim()) : "", l = q ? todas.filter(v => sin(v).includes(q)) : todas;
    if (!l.length) return pop.hidden = true;
    pop.innerHTML = l.map(v => `<div class="${v === inp.value ? "on" : ""}" data-v="${v}">${v}</div>`).join("");
    const r = inp.getBoundingClientRect(); Object.assign(pop.style, { top: r.bottom + 6 + "px", left: r.left + "px", minWidth: r.width + "px" }); pop.hidden = false; };
  inp.addEventListener("focus", () => abrir(false)); inp.addEventListener("input", () => abrir(true));
  inp.addEventListener("blur", () => setTimeout(() => pop.hidden = true, 120));
  pop.addEventListener("mousedown", e => { const o = e.target.closest("[data-v]"); if (o) { e.preventDefault(); inp.value = o.dataset.v; inp.dispatchEvent(new Event("change", { bubbles: true })); pop.hidden = true; } });
})();

