document.querySelectorAll(".mj-editor-subtareas").forEach(ed => { const l = ed.querySelector(".lista"), n = ed.querySelector(".nueva");
  const fila = t => { const d = document.createElement("div"); d.className = "it"; d.innerHTML = `<input type="checkbox" /><input type="text" /><button title="Quitar">✕</button>`; d.children[1].value = t; return d; };
  l.addEventListener("change", e => { if (e.target.type === "checkbox") e.target.parentNode.classList.toggle("ok", e.target.checked); });
  l.addEventListener("click", e => { if (e.target.tagName === "BUTTON") e.target.parentNode.remove(); });
  l.addEventListener("keydown", e => { if (e.key === "Enter") { e.preventDefault(); n.focus(); } });
  n.addEventListener("keydown", e => { if (e.key === "Enter" && n.value.trim()) { e.preventDefault(); l.appendChild(fila(n.value.trim())); n.value = ""; } });
});

