(() => { const f1 = document.getElementById("mjLdp1"), f2 = document.getElementById("mjLdp2"), err = document.getElementById("mjLdpErr");
  f1.onsubmit = e => { e.preventDefault(); const b = f1.querySelector(".go"); b.disabled = true; setTimeout(() => { b.disabled = false; f1.hidden = true; f2.hidden = false; f2.querySelector(".code").focus(); }, 500); };
  f2.onsubmit = e => { e.preventDefault(); err.hidden = false; err.textContent = "Código incorrecto. Inténtalo de nuevo."; };
  f2.querySelector(".back").onclick = () => { err.hidden = true; f2.hidden = true; f1.hidden = false; }; })();

