.mj-metricas-con-barra .barra i { display: block; height: 100%; background: var(--ink); }
.mj-metricas-con-barra .barra i.warn { background: var(--warn); } .mj-metricas-con-barra .barra i.bad { background: var(--bad); }
.mj-metricas-con-barra .grande { height: 10px; border-radius: 99px; background: #e4e3d8; overflow: hidden; margin: 18px 0 6px; }
