.mj-seccion-plegable { --cream:#f5f4ec; --cream2:#ecebe2; --line:#dcdbd0; --ink:#15161a; --ink2:#3a3a33; --muted:#6b6b62; --lime:#d6e022; --lime2:#aebb0c; --ok:#2f7d4f; --warn:#a86b00; --bad:#b42318; font-family: Inter, system-ui, sans-serif; color: var(--ink); font-size: 14px; box-sizing: border-box; }
.mj-seccion-plegable *, .mj-seccion-plegable *::before, .mj-seccion-plegable *::after { box-sizing: border-box; }
.mj-seccion-plegable { display: grid; gap: 14px; padding: 20px; background: var(--cream); interpolate-size: allow-keywords; }
.mj-seccion-plegable details::details-content { height: 0; overflow: clip; transition: height .25s cubic-bezier(.16,1,.3,1), content-visibility .25s allow-discrete; }
.mj-seccion-plegable details[open]::details-content { height: auto; }
.mj-seccion-plegable summary { list-style: none; cursor: pointer; user-select: none; }
.mj-seccion-plegable summary::-webkit-details-marker { display: none; }
.mj-seccion-plegable details.mas > summary { display: inline-flex; align-items: center; gap: 7px; font-weight: 700; font-size: 13px; color: var(--muted); }
.mj-seccion-plegable details.mas > summary::before, .mj-seccion-plegable details.subs > summary::before { content: ""; width: 6px; height: 6px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: rotate(-45deg); transition: transform .2s; }
.mj-seccion-plegable details.mas[open] > summary::before, .mj-seccion-plegable details.subs[open] > summary::before { transform: rotate(45deg); }
.mj-seccion-plegable details.mas > summary:hover { color: var(--ink); }
.mj-seccion-plegable details.subs { font-size: 13px; color: #5b5f66; }
.mj-seccion-plegable details.subs > summary { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; color: #3d4047; }
.mj-seccion-plegable .subs ul { list-style: none; margin: 6px 0 0; padding: 0; }
.mj-seccion-plegable .subs li { position: relative; padding-left: 24px; margin: 5px 0; line-height: 16px; }
.mj-seccion-plegable .subs li::before { content: ""; position: absolute; left: 0; top: 0; width: 16px; height: 16px; border: 1.5px solid #c9c9bd; border-radius: 4px; background: #fff; box-sizing: border-box; }
.mj-seccion-plegable .subs li.ok::before { content: none; }
.mj-seccion-plegable .subs li.ok::after { content: ""; position: absolute; left: 5px; top: 0; width: 5px; height: 11px; border: solid #7a9a10; border-width: 0 2.5px 2.5px 0; transform: rotate(45deg); }
.mj-seccion-plegable .subs li.ok { color: #8a8d93; text-decoration: line-through; text-decoration-color: #c9c9bd; }
.mj-seccion-plegable details.sec { background: #fff; border: 1px solid var(--line); border-radius: 14px; }
.mj-seccion-plegable details.sec > summary { padding: 12px 16px; font-weight: 700; display: flex; justify-content: space-between; }
.mj-seccion-plegable details.sec > summary::after { content: "+"; color: var(--muted); }
.mj-seccion-plegable details.sec[open] > summary::after { content: "–"; }
.mj-seccion-plegable details.sec .body { padding: 0 16px 16px; }
@media (prefers-reduced-motion: reduce) { .mj-seccion-plegable details::details-content { transition: none; } }

