.mj-consola-sql { --cream:#f5f4ec; --cream2:#ecebe2; --line:#dcdbd0; --ink:#15161a; --ink2:#3a3a33; --muted:#6b6b62; --lime:#d6e022; --lime2:#aebb0c; --ok:#2f7d4f; --warn:#a86b00; --bad:#b42318; font-family: Inter, system-ui, sans-serif; color: var(--ink); font-size: 14px; box-sizing: border-box; }
.mj-consola-sql *, .mj-consola-sql *::before, .mj-consola-sql *::after { box-sizing: border-box; }
.mj-consola-sql { padding: 20px; background: var(--cream); }
.mj-consola-sql .bases { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.mj-consola-sql .base { border: 1px solid var(--line); background: #fff; border-radius: 12px; padding: 9px 13px; cursor: pointer; font: inherit; text-align: left; color: inherit; }
