.mj-vista-publica-cliente { background: var(--cream); }
.mj-vista-publica-cliente .top { background: var(--ink); color: var(--cream); }
.mj-vista-publica-cliente .top .in, .mj-vista-publica-cliente main { max-width: 900px; margin: 0 auto; padding: 0 20px; }
.mj-vista-publica-cliente .top .in { padding-top: 28px; padding-bottom: 34px; }
.mj-vista-publica-cliente .brand { font-weight: 800; } .mj-vista-publica-cliente .brand i { font-style: normal; color: var(--lime); }
.mj-vista-publica-cliente .top small { display: block; color: #a9a99c; font-weight: 700; font-size: 12px; margin-top: 26px; text-transform: uppercase; letter-spacing: .08em; }
.mj-vista-publica-cliente .top h1 { margin: 6px 0 4px; font-size: 28px; letter-spacing: -.03em; overflow-wrap: anywhere; }
.mj-vista-publica-cliente .top p { margin: 0; color: #cfcfc4; }
.mj-vista-publica-cliente main { padding-top: 22px; padding-bottom: 50px; }
.mj-vista-publica-cliente .kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: -40px; }
.mj-vista-publica-cliente .kpi { background: #fff; border: 1px solid var(--line); border-radius: 16px; padding: 16px 18px; }
.mj-vista-publica-cliente .kpi small { color: var(--muted); font-size: 12px; font-weight: 700; }
.mj-vista-publica-cliente .kpi b { display: block; font-size: 26px; letter-spacing: -.03em; margin-top: 4px; }
.mj-vista-publica-cliente .kpi.dark { background: var(--lime); border-color: var(--lime); }
.mj-vista-publica-cliente .bar { height: 10px; border-radius: 99px; background: #e4e3d8; overflow: hidden; margin: 18px 0 6px; }
.mj-vista-publica-cliente .bar i { display: block; height: 100%; background: var(--ink); border-radius: 99px; }
.mj-vista-publica-cliente .pct { color: var(--muted); font-size: 12.5px; }
.mj-vista-publica-cliente .card { background: #fff; border: 1px solid var(--line); border-radius: 16px; margin-top: 18px; overflow: hidden; }
.mj-vista-publica-cliente .card h2 { margin: 0; padding: 16px 18px; font-size: 15px; border-bottom: 1px solid var(--line); }
.mj-vista-publica-cliente table { width: 100%; border-collapse: collapse; }
.mj-vista-publica-cliente td, .mj-vista-publica-cliente th { padding: 12px 18px; text-align: left; vertical-align: top; border-bottom: 1px solid #eeede5; }
.mj-vista-publica-cliente th { font-size: 11.5px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.mj-vista-publica-cliente .r { text-align: right; white-space: nowrap; }
.mj-vista-publica-cliente td small { display: block; color: var(--muted); margin-top: 3px; }
.mj-vista-publica-cliente td.f { white-space: nowrap; color: var(--muted); }
.mj-vista-publica-cliente tr.mes td { background: #fafaf5; font-weight: 700; font-size: 12.5px; }
.mj-vista-publica-cliente .pie { color: var(--muted); font-size: 12.5px; margin-top: 18px; line-height: 1.6; }
@media (max-width: 640px) { .mj-vista-publica-cliente .kpis { grid-template-columns: 1fr; } .mj-vista-publica-cliente .top h1 { font-size: 23px; } .mj-vista-publica-cliente td, .mj-vista-publica-cliente th { padding: 10px 12px; } .mj-vista-publica-cliente td.f { white-space: normal; width: 74px; } }

