.wp-status{display:inline-flex;align-items:center;padding:.15rem .6rem;border-radius:980px;background:var(--st-bg);color:var(--st-ink);font:500 .78rem/1.4 "Archivo",system-ui,sans-serif;white-space:nowrap}
