.wp-list__wrap{overflow-x:auto;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#fff;box-shadow:0 1px 2px rgba(19,35,63,.04),0 10px 30px -12px rgba(19,35,63,.12)}
