.wp-confirm-demo button{padding:.62rem 1.2rem;border:0;border-radius:980px;background:#fdeceb;color:#d70015;font:500 .9rem "Archivo",system-ui,sans-serif;cursor:pointer}
.wp-confirm{width:min(440px,calc(100vw - 2rem));padding:0;border:0;border-radius:20px;background:#fff;color:#13233f;box-shadow:0 40px 80px -30px rgba(19,35,63,.5);font-family:"Archivo Variable","Archivo",system-ui,sans-serif}
