@keyframes wp-confirm-in{from{opacity:0;transform:translateY(8px) scale(.98)}}
.wp-confirm__box{display:flex;flex-direction:column;gap:.8rem;padding:1.8rem 1.8rem 1.5rem}
.wp-confirm__title{margin:0;font:400 1.7rem/1.1 "Instrument Serif",Georgia,serif;text-transform:uppercase;color:#13233f}
.wp-confirm__text{margin:0;color:#56617a;line-height:1.5}
.wp-confirm__text:empty{display:none}
.wp-confirm__buttons{display:flex;justify-content:flex-end;gap:.6rem;margin-top:.8rem}
.wp-confirm__btn{padding:.7rem 1.3rem;border:0;border-radius:999px;background:#13233f;color:#fff;font:500 .9rem/1.2 "Archivo",system-ui,sans-serif;cursor:pointer}
.wp-confirm__btn:hover{background:#0a63d8}
.wp-confirm__btn--ghost{background:#fff;color:#13233f;box-shadow:inset 0 0 0 1px rgba(19,35,63,.18)}
.wp-confirm__btn--ghost:hover{background:#f3f6fa}
.wp-confirm.is-danger .wp-confirm__btn:not(.wp-confirm__btn--ghost){background:#c62f2f}

