(function(){var d=document.querySelector('.wp-confirm');if(!d)return;var t=d.querySelector('.wp-confirm__title'),x=d.querySelector('.wp-confirm__text'),ok=d.querySelector('[value=ok]'),no=d.querySelector('[value=cancel]'),pend=null;
document.addEventListener('submit',function(e){var f=e.target;if(!f.dataset||!f.dataset.confirm||f.dataset.confirmed==='1')return;e.preventDefault();e.stopImmediatePropagation();pend=f;t.textContent=f.dataset.confirmTitle||f.dataset.confirm;x.textContent=f.dataset.confirmTitle?f.dataset.confirm:'';ok.textContent=f.dataset.confirmOk||'Sí, seguir';d.classList.toggle('is-danger',f.dataset.confirmTone==='danger');d.showModal();no.focus();},true);
d.addEventListener('close',function(){if(d.returnValue==='ok'&&pend){pend.dataset.confirmed='1';pend.requestSubmit();delete pend.dataset.confirmed;}pend=null;});})();

piezas.css:
.wp-login{display:grid;grid-template-columns:1.1fr 1fr;min-height:520px;background:#f3f6fa;font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-login__photo{position:relative;overflow:hidden;background:#13233f}
.wp-login__img{position:absolute;inset:0;background:linear-gradient(160deg,#7fb3d5 0%,#d3e3ec 45%,#e9d8b4 70%,#13233f 100%)}
.wp-login__photo p{position:absolute;left:2rem;bottom:1.6rem;margin:0;color:#fff;font:500 .62rem/1.4 "Archivo",system-ui,sans-serif;font-stretch:125%;letter-spacing:.22em;text-transform:uppercase;text-shadow:0 1px 8px rgba(0,0,0,.4)}
.wp-login__side{display:flex;flex-direction:column;justify-content:center;gap:1.8rem;width:100%;max-width:400px;margin:0 auto;padding:3rem 1.5rem;box-sizing:border-box}
.wp-login__logo{font:400 1.4rem/1 "Instrument Serif",Georgia,serif;letter-spacing:.04em}
.wp-login__logo small{display:block;font:400 .75rem "Archivo",sans-serif;color:#56617a;margin-top:.3rem;letter-spacing:0}
.wp-login h1{margin:0;font:400 1.6rem/1 "Instrument Serif",Georgia,serif;text-transform:uppercase}
.wp-login h1 em{font-style:italic;text-transform:none;color:#0a63d8}
.wp-login__error{padding:.9rem 1.1rem;border-radius:12px;background:#fbeceb;color:#7a1f1f;font-size:.93rem}
.wp-login__form{display:flex;flex-direction:column;gap:1.3rem}
.wp-login__form label{display:flex;flex-direction:column;gap:.4rem;color:#56617a;font:500 .82rem/1.5 "Archivo",system-ui,sans-serif}
.wp-login__form input{min-height:44px;padding:.65rem .85rem;border:1px solid #d2d2d7;border-radius:10px;background:#fff;font:400 .95rem "Archivo",system-ui,sans-serif;color:#13233f}
.wp-login__form input:focus{outline:none;border-color:#0a63d8;box-shadow:0 0 0 4px rgba(0,113,227,.18)}
.wp-login__form button{padding:.75rem 1.2rem;border:0;border-radius:980px;background:#13233f;color:#fff;font:500 .95rem "Archivo",system-ui,sans-serif;cursor:pointer}
.wp-login__form button:hover{background:#0a63d8}
@media (max-width:800px){.wp-login{grid-template-columns:1fr}.wp-login__photo{height:30vh}}

.wp-settings{max-width:640px;padding:1.2rem 1.8rem;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#fff;box-shadow:0 1px 2px rgba(19,35,63,.04),0 10px 30px -12px rgba(19,35,63,.12);font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-set{display:flex;align-items:center;justify-content:space-between;gap:1.5rem;padding:.95rem 0}
.wp-set+.wp-set{border-top:1px solid rgba(19,35,63,.09)}
.wp-set__text{display:flex;flex-direction:column;gap:.2rem;min-width:0;cursor:pointer}
.wp-set__label{font-size:.97rem}
.wp-set__help{color:#56617a;font-size:.83rem;line-height:1.4}
.wp-set__value{display:inline-flex;flex-shrink:0;align-items:center;gap:.55rem}
.wp-set__value input{width:5.2rem;min-height:40px;padding:.45rem .6rem;text-align:right;font:400 .95rem "Archivo",system-ui,sans-serif;font-variant-numeric:tabular-nums;border:1px solid #d2d2d7;border-radius:10px;color:#13233f;box-sizing:border-box}
.wp-set__value input:focus{outline:none;border-color:#0a63d8;box-shadow:0 0 0 4px rgba(0,113,227,.18)}
.wp-set__unit{min-width:6.5rem;color:#56617a;font-size:.9rem}
@media (max-width:600px){.wp-set{flex-direction:column;align-items:stretch;gap:.6rem}}

.wp-chat{display:flex;flex-direction:column;gap:1rem;max-width:520px;padding:1rem;background:#fff;font-family:"Archivo Variable","Archivo",system-ui,sans-serif}
.wp-chat__list{display:flex;flex-direction:column;gap:.9rem;max-height:460px;margin:0;padding:.2rem;overflow-y:auto;list-style:none}
.wp-chat__msg{display:flex;flex-direction:column;align-items:flex-start;gap:.25rem;max-width:78%}
.wp-chat__msg--mine{align-self:flex-end;align-items:flex-end}
.wp-chat__bubble{margin:0;padding:.7rem 1rem;border-radius:18px 18px 18px 6px;background:#f3f6fa;color:#13233f;font-size:.95rem;line-height:1.45;white-space:pre-wrap}
.wp-chat__msg--mine .wp-chat__bubble{border-radius:18px 18px 6px 18px;background:#13233f;color:#fff}
.wp-chat__meta{padding:0 .4rem;color:#56617a;font-size:.75rem}
.wp-chat__form{display:flex;align-items:flex-end;gap:.6rem;padding:.5rem;border:1px solid rgba(19,35,63,.09);border-radius:22px;background:#fff}
.wp-chat__form:focus-within{border-color:#0a63d8}
.wp-chat__form textarea{flex:1;min-height:2.6rem;padding:.55rem .7rem;border:0;background:none;font:inherit;font-size:.95rem;resize:none}
.wp-chat__form textarea:focus{outline:none}
.wp-chat__send{flex-shrink:0;padding:.7rem 1.3rem;border:0;border-radius:999px;background:#13233f;color:#fff;font:500 .9rem "Archivo",system-ui,sans-serif;cursor:pointer}

.wp-email{display:grid;gap:1rem;padding:1rem;background:#f3f6fa;font-family:"Archivo Variable","Archivo",system-ui,sans-serif;max-width:720px}
.wp-email__tabs{display:inline-flex;justify-self:start;gap:2px;padding:3px;border-radius:10px;background:#e4ebf2}
.wp-email__tabs a{padding:.4rem .95rem;border-radius:8px;color:#13233f;font:500 .85rem "Archivo",system-ui,sans-serif;text-decoration:none}
.wp-email__tabs a[aria-current=page]{background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.12)}
.wp-email__frame{overflow:hidden;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#f6f4ef}
.wp-email__frame--movil{width:100%;max-width:390px;margin-inline:auto;border-radius:28px;border:8px solid #13233f;box-sizing:border-box}
.wp-email__frame iframe{display:block;width:100%;height:320px;border:0}
.wp-email__text{margin:0;padding:1.25rem;overflow-x:auto;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#fff;font:.85rem/1.6 ui-monospace,Menlo,monospace;white-space:pre-wrap}

.wp-btns{display:flex;flex-wrap:wrap;align-items:center;gap:.6rem;padding:1rem;background:#f3f6fa;font-family:"Archivo Variable","Archivo",system-ui,sans-serif}
.wp-btn{display:inline-flex;align-items:center;justify-content:center;gap:.55em;padding:.62rem 1.2rem;border:0;border-radius:980px;font:500 .9rem/1.2 "Archivo",system-ui,sans-serif;text-decoration:none;white-space:nowrap;cursor:pointer;transition:background .25s,color .25s,box-shadow .25s}
.wp-btn--primary{background:#13233f;color:#fff}
.wp-btn--primary:hover{background:#0a63d8}
.wp-btn--ghost{background:#fff;color:#13233f;box-shadow:inset 0 0 0 1px rgba(19,35,63,.18)}
.wp-btn--ghost:hover{box-shadow:inset 0 0 0 1px #13233f}
.wp-btn--danger{background:#fdeceb;color:#d70015}
.wp-btn--danger:hover{background:#d70015;color:#fff}
.wp-btn--sm{padding:.42rem .9rem;font-size:.82rem}
.wp-btn--link{padding:0 0 .2em;border-radius:0;border-bottom:1px solid currentColor;background:none;color:#13233f}
.wp-btn:disabled{opacity:.5;cursor:not-allowed}

.wp-hoy{max-width:560px;padding:1.6rem 1.8rem;border:1px solid rgba(19,35,63,.09);border-radius:18px;background:#fff;box-shadow:0 1px 2px rgba(19,35,63,.04),0 10px 30px -12px rgba(19,35,63,.12);font-family:"Archivo Variable","Archivo",system-ui,sans-serif;color:#13233f}
.wp-hoy__eyebrow{margin:0;color:#0a63d8;font:600 .8rem "Archivo",sans-serif}
.wp-hoy h2{margin:0 0 1.2rem;padding-bottom:.9rem;border-bottom:1px solid rgba(19,35,63,.09);font:400 1.6rem/1.05 "Instrument Serif",Georgia,serif;text-transform:uppercase}
.wp-hoy__todo{display:flex;flex-direction:column;gap:.5rem;margin:0 0 1.2rem;padding:0;list-style:none}
.wp-hoy__todo li{padding:.75rem 1rem;border-left:3px solid;border-radius:0 6px 6px 0;font-size:.93rem}
.wp-hoy__todo a{color:inherit;font-weight:600}
.wp-hoy__bad{color:#7a1f1f;background:#fbeceb;border-color:#c62f2f}
.wp-hoy__warn{color:#6b4300;background:#fff4d9;border-color:#ffb400}
.wp-hoy__info{color:#13233f;background:#d3e3ec;border-color:#0a63d8}
.wp-hoy__week{margin:0;padding:0;list-style:none}
.wp-hoy__week a{display:grid;grid-template-columns:4rem 1fr auto;align-items:center;gap:.9rem;padding:.75rem 0;border-bottom:1px solid rgba(19,35,63,.09);color:inherit;text-decoration:none}
.wp-hoy__week li:last-child a{border-bottom:0}
.wp-hoy__week a:hover .wp-hoy__who{color:#0a63d8}
.wp-hoy__day{display:flex;flex-direction:column;align-items:center;font-size:.75rem;color:#56617a}
.wp-hoy__day strong{font:400 1.6rem/1 "Instrument Serif",Georgia,serif;color:#13233f}
.wp-hoy__who small{display:block;font-size:.8rem;color:#56617a}
.wp-hoy__st{padding:.15rem .6rem;border-radius:980px;background:#d3e3ec;color:#0a63d8;font-size:.78rem;font-weight:500}

.sm-shell{display:grid;grid-template-columns:220px 1fr;min-height:360px;font-family:Manrope,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Arial,sans-serif;-webkit-font-smoothing:antialiased}
.sm-shell__side{background:#020203;color:#fff;padding:16px 10px;display:flex;flex-direction:column;gap:2px;color-scheme:dark}
.sm-shell__logo{font:400 15px/1.6 "Krona One","Manrope",Arial,sans-serif;letter-spacing:-.02em;padding:6px 10px 16px}
.sm-shell__side a{padding:7px 10px;border-radius:8px;color:#a9a9a9;font-size:13px;font-weight:500;text-decoration:none}
.sm-shell__side a:hover{background:#141416;color:#fff}
.sm-shell__side a.on{background:#1b1b1d;color:#fff;font-weight:600}
.sm-shell__main{background:#f5f5f5;padding:16px}
.sm-shell__card{background:#fff;border-radius:12px;box-shadow:0 0 0 1px rgba(2,2,3,.07),0 1px 2px rgba(2,2,3,.04);padding:24px;color:#020203}
.sm-shell__card h1{margin:0 0 4px;font:400 17px/1.6 "Krona One","Manrope",Arial,sans-serif;letter-spacing:-.02em}
.sm-shell__card p{margin:0 0 16px;color:#55555a;font-size:14px}
.sm-shell__card button{padding:6px 15px;border:0;border-radius:999px;background:#fff;box-shadow:0 0 0 1px rgba(2,2,3,.16);font:500 13px Manrope,system-ui,sans-serif;cursor:pointer}

.sm-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;padding:24px;background:#fff;font-family:Manrope,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Arial,sans-serif}
.sm-kpi{display:flex;flex-direction:column;gap:2px;background:#f5f5f5;border-radius:8px;padding:12px 16px}
.sm-kpi span{font-size:12px;color:#8f8f90}
.sm-kpi b{font-size:18px;font-weight:600;color:#020203}
.sm-kpi b.warn{color:#c2410c}
.sm-kpi b.err{color:#e11d48}
@media (max-width:768px){.sm-kpis{grid-template-columns:repeat(2,1fr)}}

.sm-prod{display:flex;flex-direction:column;width:300px;overflow:hidden;background:#fff;border-radius:12px;box-shadow:0 0 0 1px rgba(2,2,3,.07),0 1px 2px rgba(2,2,3,.04);font-family:Manrope,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Arial,sans-serif;color:#020203}
.sm-prod__foto{position:relative;display:block;aspect-ratio:4/3;background:#f5f5f5;cursor:pointer;overflow:hidden}
.sm-prod__img{position:absolute;inset:0;background:linear-gradient(135deg,#2a2a2c,#8f8f90)}
.sm-prod__over{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);padding:6px 12px;border-radius:999px;background:#fff;color:#000;font-size:13px;font-weight:600;opacity:0;transition:opacity .2s}
.sm-prod__foto:hover::after{content:"";position:absolute;inset:0;background:rgba(0,0,0,.45)}
.sm-prod__foto:hover .sm-prod__over{opacity:1;z-index:1}
.sm-prod__foto.is-over{box-shadow:inset 0 0 0 2px #020203}
.sm-prod__body{display:flex;flex-direction:column;gap:16px;padding:16px}
.sm-prod__head{display:flex;justify-content:space-between;gap:12px}
.sm-prod__head h3{margin:0;font-size:15px;font-weight:600}
.sm-prod__head p{margin:0;font-size:13px;color:#55555a}
.sm-prod__switch{display:flex;align-items:center;gap:8px;font-size:12px;color:#55555a}
.sm-prod__switch button{width:32px;height:18px;border-radius:999px;border:0;background:#020203;padding:2px;cursor:pointer;display:flex;justify-content:flex-end}
.sm-prod__switch button[aria-checked=false]{background:#d4d4d8;justify-content:flex-start}
.sm-prod__switch i{width:14px;height:14px;border-radius:50%;background:#fff}
.sm-prod__linea{display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#8f8f90}
.sm-prod__seg{display:flex;gap:4px;padding:4px;border-radius:999px;background:#f5f5f5}
.sm-prod__seg button{padding:4px 10px;border:0;border-radius:999px;background:none;font:600 12px Manrope,sans-serif;color:#55555a;cursor:pointer}
.sm-prod__seg button[aria-checked=true]{background:#fff;color:#020203;box-shadow:0 0 0 1px rgba(2,2,3,.07),0 1px 2px rgba(2,2,3,.04)}
.sm-prod__datos{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.sm-prod__datos div{background:#f5f5f5;border-radius:8px;padding:8px 12px}
.sm-prod__datos span{display:block;font-size:12px;color:#8f8f90}
.sm-prod__datos b{font-size:14px}
.sm-prod__datos b.warn{color:#c2410c}
.sm-prod__acc{display:flex;flex-wrap:wrap;gap:8px}
.sm-prod__acc button,.sm-prod__acc a{padding:5px 13px;border:0;border-radius:999px;background:#fff;box-shadow:0 0 0 1px rgba(2,2,3,.16);font:500 13px Manrope,sans-serif;color:#020203;text-decoration:none;cursor:pointer}
.sm-prod__acc a{box-shadow:none}

.sm-orders{display:flex;flex-direction:column;gap:12px;padding:16px;background:#f5f5f5;font-family:Manrope,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Arial,sans-serif;color:#020203;max-width:820px}
.sm-orders__bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px}
.sm-orders__bar small{font-size:13px;color:#8f8f90}
.sm-orders__seg{display:flex;gap:4px;padding:4px;border-radius:999px;background:#ececec}
.sm-orders__seg button{padding:6px 12px;border:0;border-radius:999px;background:none;font:600 13px Manrope,sans-serif;color:#55555a;cursor:pointer}
.sm-orders__seg button.on{background:#fff;color:#020203;box-shadow:0 0 0 1px rgba(2,2,3,.07),0 1px 2px rgba(2,2,3,.04)}
.sm-orders__seg span{color:#8f8f90;margin-left:6px}
.sm-order{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,2fr) auto;align-items:center;gap:16px;padding:16px;background:#fff;border-radius:12px;box-shadow:0 0 0 1px rgba(2,2,3,.07),0 1px 2px rgba(2,2,3,.04)}
.sm-order__n{display:flex;align-items:center;gap:8px;font-weight:600;font-size:14px}
.sm-order small{font-size:13px;color:#55555a}
.sm-order__badge{padding:1px 6px;border-radius:6px;font-size:11px;font-weight:500;background:#ffedd5;color:#c2410c}
.sm-order__badge.blue{background:#dbeafe;color:#1d4ed8}
.sm-order ul{margin:0;padding:0;list-style:none;font-size:13px}
.sm-order ul span{color:#8f8f90}
.sm-order ul em{font-style:normal;color:#55555a}
.sm-order__end{display:flex;align-items:center;gap:16px;justify-content:flex-end}
.sm-order__end b{font-size:14px}
.sm-order__btn{padding:5px 13px;border-radius:999px;background:#fff;box-shadow:0 0 0 1px rgba(2,2,3,.16);font:500 13px Manrope,sans-serif;color:#020203;text-decoration:none}
.sm-order__btn.primary{background:#020203;color:#fff}
@media (max-width:768px){.sm-order{grid-template-columns:1fr}.sm-order__end{justify-content:space-between}}

.sm-drawer{display:flex;flex-direction:column;width:380px;max-width:100%;min-height:420px;background:#fff;border-radius:12px;box-shadow:0 0 0 1px rgba(2,2,3,.1),0 8px 24px rgba(2,2,3,.08);font-family:Manrope,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Arial,sans-serif;color:#020203}
.sm-drawer header{padding:16px 24px;border-bottom:1px solid rgba(2,2,3,.09)}
.sm-drawer h2{margin:0;font:400 15px/1.6 "Krona One","Manrope",Arial,sans-serif}
.sm-drawer header p{margin:0;font-size:13px;color:#55555a}
.sm-drawer__body{flex:1;display:flex;flex-direction:column;gap:16px;padding:24px}
.sm-drawer__todas{display:flex;flex-direction:column;gap:12px;background:#f5f5f5;border-radius:8px;padding:16px}
.sm-drawer__todas label,.sm-drawer__fila label{font-size:13px;font-weight:600}
.sm-drawer__todas div{display:flex;gap:8px}
.sm-drawer input{flex:1;min-width:0;padding:6px 10px;border:0;border-radius:8px;box-shadow:0 0 0 1px rgba(2,2,3,.1);font:400 13px Manrope,sans-serif;background:#fff}
.sm-drawer button{padding:6px 15px;border:0;border-radius:999px;background:#fff;box-shadow:0 0 0 1px rgba(2,2,3,.16);font:500 13px Manrope,sans-serif;cursor:pointer;color:#020203}
.sm-drawer button.primary{background:#020203;color:#fff}
.sm-drawer__fila{display:grid;grid-template-columns:1fr 9rem;align-items:center;gap:16px}
.sm-drawer__fila small{display:block;font-size:12px;color:#8f8f90}
.sm-drawer__fila em{font-style:normal;color:#020203;font-weight:600}
.sm-drawer__eur{position:relative;display:flex}
.sm-drawer__eur input{text-align:right;padding-right:28px}
.sm-drawer__eur span{position:absolute;right:12px;top:50%;transform:translateY(-50%);font-size:13px;color:#8f8f90;pointer-events:none}
.sm-drawer footer{display:flex;justify-content:flex-end;gap:8px;padding:16px 24px;border-top:1px solid rgba(2,2,3,.09)}

.sm-promo{display:flex;flex-direction:column;gap:12px;width:340px;padding:16px;background:#fff;border-radius:12px;box-shadow:0 0 0 1px rgba(2,2,3,.07),0 1px 2px rgba(2,2,3,.04);font-family:Manrope,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Arial,sans-serif;color:#020203}
.sm-promo__head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
.sm-promo__head>div{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.sm-promo__code{padding:4px 10px;border:1px dashed rgba(2,2,3,.16);border-radius:6px;background:#f5f5f5;font:600 14px ui-monospace,Menlo,monospace;letter-spacing:.08em}
.sm-promo__auto{padding:1px 6px;border-radius:6px;background:#f3e8ff;color:#7e22ce;font-size:11px;font-weight:500}
.sm-promo__st{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:500;color:#020203}
.sm-promo__st::before{content:"";width:8px;height:8px;border-radius:2px;background:#10b981}
.sm-promo__sum{margin:0;font-size:13px;color:#55555a}
.sm-promo__prev{font-size:13px;color:#55555a;background:#f5f5f5;border-radius:8px;padding:8px 12px}
.sm-promo__prev strong{color:#020203}
.sm-promo__pie{display:flex;justify-content:space-between;align-items:center;font-size:13px}
.sm-promo__pie label{display:flex;align-items:center;gap:8px}
.sm-promo__pie [role=switch]{width:32px;height:18px;border-radius:999px;border:0;background:#020203;padding:2px;display:flex;justify-content:flex-end;cursor:pointer}
.sm-promo__pie [role=switch] i{width:14px;height:14px;border-radius:50%;background:#fff}
