.ar-barra{display:flex;align-items:center;gap:14px;background:#16160f;color:#f4f3ee;border-radius:18px;padding:8px 8px 8px 18px;border:1px solid rgba(244,243,238,.08);box-shadow:0 8px 24px -16px rgba(0,0,0,.5);font-family:Inter,system-ui,-apple-system,sans-serif;font-size:14px;max-width:820px}
