.ar-slots{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}
.ar-slot{border:1.5px dashed rgba(107,107,102,.45);border-radius:999px;padding:6px 12px;background:none;cursor:pointer;white-space:nowrap;font:500 14px Inter,system-ui,sans-serif;color:#6b6b66;display:inline-flex;align-items:center;gap:6px;transition:background .15s,border-color .15s,color .15s,transform .15s,box-shadow .15s}
