.ar-semana{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;background:#fff;border:1px solid #e6e4dd;border-radius:18px;padding:14px 16px;font-family:Inter,system-ui,-apple-system,sans-serif;font-size:14px;color:#111;max-width:820px}
