.fi-tabs{position:relative;display:inline-flex;gap:2px;padding:3px;background:#ece9de;border-radius:9999px;font-family:-apple-system,BlinkMacSystemFont,Inter,'SF Pro Text',ui-sans-serif,system-ui,sans-serif}
