.fi-tab__badge{display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;padding:0 5px;border-radius:9999px;background:#a3352b;color:#fff;font-size:.68rem;font-weight:700;margin-left:.3rem;box-sizing:border-box}

.fi-toasts{display:flex;flex-direction:column;gap:.6rem;max-width:min(360px,calc(100vw - 2rem));padding:1rem;background:#f7f6f0;font-family:-apple-system,BlinkMacSystemFont,Inter,'SF Pro Text',ui-sans-serif,system-ui,sans-serif;color:#15161a}
