.fi-jornada summary{list-style:none;cursor:pointer;display:grid;grid-template-columns:minmax(0,1.6fr) repeat(3,minmax(0,.8fr)) minmax(0,1fr) 104px 18px;align-items:center;gap:.75rem;padding:.75rem 1rem;border-radius:14px}
.fi-jornada summary::-webkit-details-marker{display:none}
.fi-jornada__nombre{font-weight:600;font-size:.92rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fi-jornada__dato{display:flex;flex-direction:column;font-size:.88rem;font-variant-numeric:tabular-nums}
