.fi-jornada__horas{font-weight:700}
.fi-jornada__estado{justify-self:end;padding:.2rem .65rem;border-radius:9999px;font-size:.72rem;font-weight:600;white-space:nowrap;background:rgba(21,22,26,.06);color:#3a3a33}
.fi-jornada--sin-cerrar{border-color:rgba(163,53,43,.25)}
.fi-jornada--sin-cerrar .fi-jornada__estado{background:rgba(163,53,43,.1);color:#a3352b}
.fi-jornada__chev{opacity:.5;transition:transform .25s}
.fi-jornada[open] .fi-jornada__chev{transform:rotate(180deg)}
.fi-jornada__ev{list-style:none;margin:0;padding:.25rem 1rem .9rem;border-top:1px solid rgba(21,22,26,.06)}
.fi-jornada__ev li{display:flex;align-items:center;gap:.75rem;padding:.45rem 0;font-size:.85rem}
.fi-jornada__ev li+li{border-top:1px dashed rgba(21,22,26,.07)}
.fi-jornada__ev .ubi{margin-left:auto;font-size:.78rem}
@media (max-width:760px){.fi-jornada summary{grid-template-columns:repeat(3,minmax(0,1fr)) minmax(0,1.25fr) 18px;grid-template-areas:"n n n e c" "a b p h h";row-gap:.55rem}
.fi-jornada__nombre{grid-area:n}.fi-jornada__estado{grid-area:e}.fi-jornada__chev{grid-area:c}.fi-jornada__horas{grid-area:h}}

.fi-mes{width:300px;padding:1rem;background:#f7f6f0;font-family:-apple-system,BlinkMacSystemFont,Inter,'SF Pro Text',ui-sans-serif,system-ui,sans-serif;color:#15161a}
