.fi-sol__acc{display:flex;gap:.5rem;flex-shrink:0}
.fi-cambio{display:inline-flex;flex-wrap:wrap;align-items:center;gap:.4rem;font-size:.88rem;font-variant-numeric:tabular-nums}
.fi-cambio s{color:#3a3a33;text-decoration-thickness:1.5px}.fi-cambio__fl{color:#aebb0c;font-weight:700}
.fi-btn{display:inline-flex;align-items:center;border-radius:9999px;padding:.48rem 1.05rem;font:600 .82rem inherit;font-family:inherit;border:1px solid transparent;cursor:pointer;transition:transform .25s,background .2s,color .2s}
.fi-btn--primary{background:#d6e022;color:#15161a}.fi-btn--primary:hover{transform:translateY(-1px);background:#15161a;color:#d6e022}
.fi-btn--danger{background:rgba(163,53,43,.08);color:#a3352b}.fi-btn--danger:hover{background:rgba(163,53,43,.14)}
.fi-sol__sep{margin:1.6rem 0 .5rem;padding-top:1rem;border-top:1px solid rgba(21,22,26,.08);font-size:.95rem;font-weight:700}
.fi-res{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1.4fr) auto;align-items:center;gap:.25rem 1rem;padding:.7rem 1rem;font-size:.86rem;border:1px solid rgba(21,22,26,.07);border-radius:14px;background:#fff}
.fi-res .n{font-weight:600}.fi-res .d{color:#3a3a33}
.fi-badge{padding:.22rem .7rem;border-radius:9999px;font-size:.74rem;font-weight:600}
.fi-badge.ok{background:rgba(90,140,90,.16);color:#2f6b2f}
@media (max-width:640px){.fi-sol{flex-direction:column;align-items:stretch}.fi-sol__acc .fi-btn{flex:1;justify-content:center}.fi-res{grid-template-columns:1fr auto}}
